import re

def _parse_version(v_str: str) -> tuple[int, int, int]:
    if not isinstance(v_str, str):
        raise ValueError("Version must be a string")
    parts = v_str.split('.')
    if len(parts) != 3:
        raise ValueError(f"Invalid semver: '{v_str}'")
    parsed = []
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"Invalid semver component: '{p}'")
        parsed.append(int(p))
    return tuple(parsed)

def _compare(v: tuple[int, int, int], op: str, target: tuple[int, int, int]) -> bool:
    if op == '=':
        return v == target
    elif op == '>=':
        return v >= target
    elif op == '<=':
        return v <= target
    elif op == '>':
        return v > target
    elif op == '<':
        return v < target
    else:
        raise ValueError(f"Unknown operator: '{op}'")

def satisfies(version: str, spec: str) -> bool:
    v = _parse_version(version)
    if not isinstance(spec, str) or not spec.strip():
        raise ValueError("Spec must be a non-empty string")

    spec = spec.strip()

    if spec.startswith('^'):
        target = _parse_version(spec[1:])
        maj, min_, pat = target
        if maj != 0:
            upper = (maj + 1, 0, 0)
        elif min_ != 0:
            upper = (0, min_ + 1, 0)
        else:
            return v == target
        return v >= target and v < upper

    if spec.startswith('~'):
        target = _parse_version(spec[1:])
        maj, min_, pat = target
        upper = (maj, min_ + 1, 0)
        return v >= target and v < upper

    # Otherwise, space-separated conjunction of comparators or an exact version
    tokens = spec.split()
    for token in tokens:
        match = re.match(r'^(>=|<=|>|<|=)?(\d+\.\d+\.\d+)$', token)
        if not match:
            raise ValueError(f"Invalid comparator or version in spec: '{token}'")
        op, target_str = match.groups()
        target = _parse_version(target_str)
        op = op if op else '='
        if not _compare(v, op, target):
            return False

    return True
